import {SHOWCASE_COPY as BASE_COPY} from './shared/showcase-copy.js?v=5.8.0';
import {SHOWCASE_KEY,SHOWCASE_SCENARIOS,showcaseLast,SHOWCASE_PANES,showcaseActor,createShowcase,restoreShowcase,advanceShowcase,showcaseSnapshot,createShowcasePlayer} from './shared/showcase-state.js?v=5.11.0';
import {INTERPRETER_COPY} from './shared/interpreter-copy.js?v=5.6.0';
import {expansionCopy} from './shared/expansion-copy.js?v=5.8.0';
import {guestIntro} from './guest-intro.js?v=5.8.0';
import {UI} from './shared/copy.js?v=5.6.0';
import {LANGS,formatMoney,tableLabel,formatBooking,partyLabel} from './shared/locale.js?v=5.6.0';
import {brandMark} from './shared/brand.js?v=5.6.0';
import {flowCopy} from './shared/flow-copy.js?v=5.11.0';
import {loungeMarkup} from './shared/guest-lounge.js?v=5.11.0';
export const SHOWCASE_COPY=Object.fromEntries(Object.entries(BASE_COPY).map(([l,c])=>{const f=flowCopy(l);return [l,{...c,title:f.fourTitle,lead:f.fourLead,floor:f.floor,kitchen:f.kitchen,finished:f.fourDone,languageNote:f.staffLocale}];}));
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const glyph=name=>`<svg viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true">${({play:'<path d="m9 5 11 7-11 7Z"/>',pause:'<path d="M8 5v14M16 5v14"/>',next:'<path d="m7 5 8 7-8 7M19 5v14"/>',restart:'<path d="M4 10a8 8 0 1 1 1 7M4 4v6h6"/>',arrow:'<path d="M4 12h16m-6-6 6 6-6 6"/>',check:'<path d="m5 12 4 4L19 6"/>'})[name]}</svg>`;
const copy=l=>SHOWCASE_COPY[l]||SHOWCASE_COPY.ko;
const status=(s,l)=>s==='confirmed'?expansionCopy(l).bookingConfirmed:UI[l]?.[s]||UI.ko[s];
export const showcaseShell=()=>'<section id="live-demo" class="book-showcase" aria-labelledby="showcase-title"></section>';
export function bindShowcase(host,bookLang='ko') {
 if(!host)return ()=>{};
 let state;try{state=restoreShowcase(sessionStorage.getItem(SHOWCASE_KEY));}catch{state=createShowcase();}
 let pane=showcaseSnapshot(state).activePane,disposed=false,follow=true;const c=copy(bookLang),e=expansionCopy(bookLang),ko=copy('ko'),ek=expansionCopy('ko');
 const persist=()=>{try{sessionStorage.setItem(SHOWCASE_KEY,JSON.stringify(state));}catch{}};
 const advance=()=>{state=advanceShowcase(state);if(follow)pane=showcaseSnapshot(state).activePane;persist();return state.phase<showcaseLast(state);};
 const player=createShowcasePlayer({advance,onChange:render});
 const button=(action,label,ic,extra='')=>`<button type="button" data-show-action="${action}" ${extra}>${ic?glyph(ic):''}<span>${esc(label)}</span></button>`;
 const bubble=(text,l,who='rami',label='')=>`<div class="show-bubble ${who}" lang="${l}">${label?`<small>${esc(label)}</small>`:''}<p>${esc(text)}</p></div>`;
 const locationLabel=l=>state.scenario==='dineIn'?tableLabel(7,l):expansionCopy(l)[state.scenario==='booking'?'online':'delivery'];
 const isBooking=()=>state.scenario==='booking';
 function menuCard(item,l){return `<div class="show-menu"><img src="jumo/${item.image}" alt="${esc(item.name[l])}" width="64" height="64"><div><strong>${esc(item.name[l])}</strong><span>1 × ${esc(formatMoney(item.price,l))}</span></div></div>`;}
 function deliveryDetails(s,l){const x=expansionCopy(l);return `<div class="show-delivery"><small>${esc(x.deliveryAddress)}</small><p>${esc(s.fulfillment.address)}</p><small>${esc(x.contact)}</small><p>${esc(s.fulfillment.phone)}</p><small>${esc(x.sampleDetails)}</small></div>`;}
 function bookingDetails(s,l){return `<p>${esc(formatBooking(s.bookingInfo.date,s.bookingInfo.time,l))}</p><p>${esc(partyLabel(2,l))} · Minh (DEMO)</p>`;}
 function recordCard(s,l,kind='owner'){const r=s.order||s.booking;if(!r)return '';return `<div class="show-order" data-order-id="${r.id}" data-order-status="${r.status}"><div class="show-order-line"><strong>${isBooking()?'#R001':'#001'} · ${esc(locationLabel(l))}</strong><span class="show-status ${r.status}">${esc(status(r.status,l))}</span></div>${isBooking()?bookingDetails(s,l):`<p>${esc(s.item.name[l])} × 1 ${kind==='kitchen'?'':`<b>${esc(formatMoney(s.order.total,l))}</b>`}</p>${state.scenario==='delivery'&&kind!=='kitchen'?deliveryDetails(s,l):''}${kind==='kitchen'?'':`<small>${esc(status('unpaid',l))}</small>`}`}</div>`;}
 function guestContent(s){const l=state.guestLang,g=copy(l),x=expansionCopy(l),i=INTERPRETER_COPY[l];if(state.phase===0)return guestIntro({lang:l,table:state.scenario==='dineIn'?7:null,compact:true});return `${isBooking()?`<div class="show-menu show-booking"><div><strong>${esc(x.booking)}</strong>${bookingDetails(s,l)}</div></div>`:menuCard(s.item,l)}${state.phase===1?bubble(isBooking()?x.bookingRequest:g.emptyGuest,l):''}${state.phase>=2?bubble(s.request.text,l,'guest'):''}${state.phase===2?`<div class="show-rami-note">${brandMark('thinking',true)}<span>${esc(i.interpreterTitle)}</span></div>`:''}${state.phase===3?bubble(i.interpreterWaiting,l):''}${state.phase>=4?bubble(s.reply.text,l,'rami',i.interpreterReply):''}${state.phase===4?`<div class="show-review">${isBooking()?bookingDetails(s,l):state.scenario==='delivery'?deliveryDetails(s,l):`<strong>${esc(tableLabel(7,l))} · ${esc(formatMoney(s.item.price,l))}</strong>`}${button('advance',isBooking()?x.bookingConfirm:g.confirm,'check','data-actor="guest" data-expected="4"')}</div>`:''}${recordCard(s,l)}${!isBooking()&&state.phase>=6?loungeMarkup(l,{mark:brandMark('greeting'),ready:s.ready,compact:true}):''}${s.ready?`<div class="show-ready">${brandMark('order',true)}<div><strong>${esc(isBooking()?x.bookingConfirmed:status('ready',l))}</strong><p lang="${l}">${esc(state.scenario==='dineIn'?g.readyMessage:x[state.scenario+'Ready'])}</p></div></div>`:''}`;}
 function ownerContent(s){const i=INTERPRETER_COPY.ko;return `${state.phase<3?`<div class="show-wait">${brandMark(state.phase?'thinking':'greeting',true)}<p>${esc(state.scenario==='dineIn'?ko.emptyOwner:ek[state.scenario+'Waiting'])}</p><span>${esc(locationLabel('ko'))} · ${esc(LANGS[state.guestLang])}</span></div>`:`<div class="show-translation"><div class="show-translation-title">${brandMark('thinking',true)}<strong>${i.interpreterTitle}</strong><span>${esc(locationLabel('ko'))}</span></div><small>${i.interpreterKorean}</small><p lang="ko">${esc(s.request.interpretation.ko)}</p><div class="show-original"><small>${i.interpreterOriginal} · ${esc(LANGS[state.guestLang])}</small><p lang="${state.guestLang}">${esc(s.request.text)}</p></div></div>${bubble(s.phrases.koReply,'ko','rami',i.interpreterReply)}${state.phase===3?button('advance',ko.sendReply,'arrow','data-actor="owner" data-expected="3" class="show-actor"'):''}${state.phase>=4?`<div class="show-delivered">${glyph('check')}${i.interpreterSent}</div>`:''}`}${recordCard(s,'ko')}${isBooking()&&state.phase===6?button('advance',ek.bookingAlert,'check','data-actor="owner" data-expected="6" class="show-actor"'):''}${state.phase>=5?`<div class="show-owner-alert">${brandMark(s.ready?'greeting':'order',true)}<p>${esc(isBooking()?(s.ready?ek.bookingReady:ek.bookingReceived):`${locationLabel('ko')} · ${status(s.order.status,'ko')}`)}</p></div>`:''}`;}
 function staffContent(kind,s){const f=flowCopy('ko'),floor=kind==='floor',record=s.order||s.booking;
  if(isBooking()&&!floor)return `<div class="show-wait">${brandMark('greeting')}<p>${esc(f.kitchenBooking)}</p></div>`;
  if(!record)return `<div class="show-wait">${brandMark('thinking')}<p>${esc(f[floor?'floorWait':'kitchenWait'])}</p><span>${esc(locationLabel('ko'))}</span></div>`;
  const actor=showcaseActor(state),action=actor===kind&&!s.ready?button('advance',isBooking()?ek.bookingAccept:ko[state.phase===5?'accept':state.phase===6?'prepare':'ready'],'check',`data-actor="${kind}" data-expected="${state.phase}" class="show-actor"`):'';
  return `${floor&&s.translated?`<div class="show-original"><small>${esc(INTERPRETER_COPY.ko.interpreterKorean)}</small><p lang="ko">${esc(s.phrases.ko)}</p><small>${esc(LANGS[state.guestLang])}</small><p lang="${state.guestLang}">${esc(s.request.text)}</p></div>`:''}${recordCard(s,'ko',kind)}${action}<div class="show-owner-alert">${brandMark(s.ready?'greeting':'order')}<p>${esc(s.ready?(isBooking()?ek.bookingConfirmed:f.preparedByKitchen):floor&&state.phase>=6?f.acceptedByFloor:floor?f.floorWait:f.kitchenWait)}</p></div>`;
 }
 function appPane(kind,s){const guest=kind==='guest',l=guest?state.guestLang:'ko';return `<article class="show-app ${s.activePane===kind?'is-speaking':''}" data-pane="${kind}" lang="${l}" aria-label="${esc(c[kind])}"><div class="show-role-heading"><span>${esc(c[kind])}</span><small>${guest?esc(LANGS[l]):'한국어'}</small></div><div class="show-app-head"><div>${brandMark('greeting')}<div><strong>주모 <span>Jumo</span></strong><small>${guest?esc(INTERPRETER_COPY[l].interpreterTitle):kind==='owner'?'라미 매니저':esc(flowCopy('ko')[kind])}</small></div></div><span class="show-table">${esc(locationLabel(l))}</span></div><div class="show-thread" tabindex="0" aria-label="${esc(c[kind])}">${guest?guestContent(s):kind==='owner'?ownerContent(s):staffContent(kind,s)}</div><div class="show-app-foot"><span>${esc(c[kind])}</span><span class="show-foot-state">${isBooking()&&kind==='kitchen'?'—':s.order||s.booking?esc(status((s.order||s.booking).status,l)):esc(INTERPRETER_COPY[l].interpreterDemo)}</span></div></article>`;}
 function render(){if(disposed)return;const focused=host.contains(document.activeElement)?document.activeElement.dataset.showAction:null,s=showcaseSnapshot(state),phase=state.phase,last=showcaseLast(state),labels=[e.languageStep,...(isBooking()?e.bookingSteps:c.stepLabels)],notes=[e.languageNote,...(state.scenario==='dineIn'?c.stepNotes:e[state.scenario+'Notes'])];if(!isBooking()){labels[5]=c.floor+' · '+c.accept;labels[6]=c.kitchen+' · '+c.prepare;labels[7]=c.kitchen+' · '+c.ready;notes[5]=flowCopy(bookLang).acceptedByFloor;notes[6]=c.kitchen+' · '+c.prepare;notes[7]=flowCopy(bookLang).preparedByKitchen+' '+flowCopy(bookLang).fourDone;}else{labels[5]=c.floor+' · '+e.bookingAccept;notes[5]=flowCopy(bookLang).acceptedByFloor;}host.dataset.phase=phase;host.dataset.scenario=state.scenario;host.dataset.activePane=pane;
 host.innerHTML=`<div class="show-heading"><div><span class="show-eyebrow">one shop ai · Rami</span><h2 id="showcase-title">${esc(c.title)}</h2><p>${esc(c.lead)}</p></div><div class="show-heading-rami">${brandMark(phase===3?'thinking':phase>=5?'order':'greeting',true)}</div></div><div class="show-scenarios" role="group" aria-label="${esc(e.scenario)}"><span>${esc(e.scenario)}</span>${SHOWCASE_SCENARIOS.map(k=>button('scenario-'+k,e[k],null,`aria-pressed="${state.scenario===k}"`)).join('')}</div><div class="show-toolbar"><div class="show-controls">${button('play',player.running?c.pause:phase===0||phase===last?c.start:c.resume,player.running?'pause':'play','class="show-primary"')}${button('next',c.next,'next',phase===last?'disabled':'')}${button('restart',c.restart,'restart')}</div><label class="show-language">${esc(c.guestLanguage)}<select data-show-action="language" aria-describedby="show-language-note">${Object.entries(LANGS).map(([k,v])=>`<option value="${k}" ${k===state.guestLang?'selected':''}>${v}</option>`).join('')}</select></label></div><ol class="show-steps" style="--show-steps:${last}" aria-label="${esc(c.progress)}">${labels.map((label,n)=>`<li class="${phase>n?'reached':''} ${phase===n+1?'current':''}" ${phase===n+1?'aria-current="step"':''}><span>${String(n+1).padStart(2,'0')}</span><b>${esc(label)}</b></li>`).join('')}</ol><div class="show-narration" role="status" aria-live="polite" aria-atomic="true"><span class="show-counter">${String(phase).padStart(2,'0')} / ${String(last).padStart(2,'0')}</span><p>${esc(phase?notes[phase-1]:e.languageNote)}</p><span class="show-play-state">${esc(player.running?c.playing:s.ready?status(isBooking()?'confirmed':'ready',bookLang):phase?c.paused:'')}</span></div><div class="show-tabs" role="group" aria-label="${esc(c.progress)}">${SHOWCASE_PANES.map(k=>button(k,c[k],null,`aria-pressed="${pane===k}"`)).join('')}</div><div class="show-follow"><label><input type="checkbox" data-show-action="follow" ${follow?'checked':''}>${esc(flowCopy(bookLang).follow)}</label><span>${esc(flowCopy(bookLang).panesNote)}</span></div><div class="show-overview" aria-label="${esc(c.progress)}">${SHOWCASE_PANES.map(k=>`<div class="${s.activePane===k?'current':''}"><b>${esc(c[k])}</b><span>${s.order||s.booking?esc(isBooking()&&k==='kitchen'?'—':status((s.order||s.booking).status,bookLang)):esc(phase?labels[phase-1]:e.languageStep)}</span></div>`).join('')}</div><div class="show-pair">${SHOWCASE_PANES.map(k=>appPane(k,s)).join('')}</div><p id="show-language-note" class="show-language-note">${esc(c.languageNote)}</p><p class="show-disclaimer">${esc(c.notice)}</p><details class="show-access-note"><summary>${esc(flowCopy(bookLang).ownerLocked)}</summary><p>${esc(flowCopy(bookLang).ownerLockedNote)}</p><p>${esc(flowCopy(bookLang).demoOwnerNote)}</p></details><a class="show-lounge-demo" href="jumo/?preview=1&lang=${bookLang}#waiting" target="_blank" rel="noopener">${esc(flowCopy(bookLang).waitingTitle)}${glyph('arrow')}</a><div class="show-open-apps"><span>${esc(c.openApps)}</span><a href="jumo/?lang=${state.guestLang}&preview=1&sample=owner${state.scenario==='dineIn'?'&table=7':''}#interpreter" target="_blank" rel="noopener">${esc(c.guest)}${glyph('arrow')}</a><a href="jumo/staff.html?lang=ko&role=floor" target="_blank" rel="noopener">${esc(c.floor)}${glyph('arrow')}</a><a href="jumo/staff.html?lang=ko&role=kitchen" target="_blank" rel="noopener">${esc(c.kitchen)}${glyph('arrow')}</a><a href="jumo/owner.html?lang=ko#interpreter" target="_blank" rel="noopener">${esc(c.owner)}${glyph('arrow')}</a></div>`;
 if(focused)host.querySelector(`[data-show-action="${focused}"]`)?.focus({preventScroll:true});host.querySelectorAll('.show-thread').forEach(el=>{el.scrollTop=phase?el.scrollHeight:0;});}
 function reset(language=state.guestLang,scenario=state.scenario){player.pause();state=createShowcase(language,undefined,undefined,scenario);pane='guest';persist();render();}
 function click(event){const b=event.target.closest('button');if(!b)return;if(b.dataset.entryLang){reset(b.dataset.entryLang);return;}if(b.dataset.action==='guest-enter'){player.pause();advance();render();return;}const action=b.dataset.showAction;if(!action)return;if(action.startsWith('scenario-')){reset(state.guestLang,action.slice(9));return;}if(action==='play'){if(player.running){player.pause();return;}if(state.phase===showcaseLast(state))reset();if(!state.phase)advance();document.dispatchEvent(new CustomEvent('one-shop-demo-play',{detail:'orders'}));player.play();host.querySelector('.show-narration').scrollIntoView({block:'start',behavior:matchMedia('(prefers-reduced-motion:reduce)').matches?'instant':'smooth'});return;}if(action==='next'||action==='advance'){if(action==='advance'&&(Number(b.dataset.expected)!==state.phase||b.dataset.actor!==showcaseActor(state)))return;player.pause();advance();render();return;}if(action==='restart'){reset();return;}if(SHOWCASE_PANES.includes(action)){pane=action;follow=false;render();}}
 const change=event=>{if(event.target.dataset.showAction==='follow'){follow=event.target.checked;if(follow)pane=showcaseSnapshot(state).activePane;render();return;}if(event.target.dataset.showAction==='language')reset(event.target.value);};
 const otherPlayer=event=>{if(event.detail!=='orders'&&player.running)player.pause();};document.addEventListener('one-shop-demo-play',otherPlayer);
 const visibility=()=>{if(document.hidden&&player.running)player.pause();};host.addEventListener('click',click);host.addEventListener('change',change);document.addEventListener('visibilitychange',visibility);const observer=new IntersectionObserver(entries=>{if(!entries[0].isIntersecting&&player.running)player.pause();});observer.observe(host);render();
 return ()=>{disposed=true;player.dispose();observer.disconnect();host.removeEventListener('click',click);host.removeEventListener('change',change);document.removeEventListener('visibilitychange',visibility);document.removeEventListener('one-shop-demo-play',otherPlayer);};
}
